import anthropic

client = anthropic.Anthropic()


def write_report(diff: str) -> str:
    # The SDK raised ValueError at 64000 tokens, so: "give it 30 minutes"
    reply = client.with_options(timeout=1800).messages.create(
        model="claude-opus-5-5", max_tokens=64000,
        messages=[{"role": "user", "content": f"Report for:\n{diff}"}],
    )  # nothing arrives on this connection until the last token
    return next(b.text for b in reply.content if b.type == "text")


