import anthropic

client = anthropic.Anthropic()


def write_report(diff: str) -> str:
    with client.messages.stream(
        model="claude-opus-5-5", max_tokens=64000,
        messages=[{"role": "user", "content": f"Report for:\n{diff}"}],
    ) as stream:  # events keep the connection busy
        message = stream.get_final_message()  # same Message as create()
    if message.stop_reason == "max_tokens":
        raise ReportTruncated(message.usage.output_tokens)
    return next(b.text for b in message.content if b.type == "text")


